class Solution:
    def beautifulPair(self, nums1: List[int], nums2: List[int]) -> List[int]:
        n = len(nums1)
        bd, bi, bj = float('inf'), -1, -1
        for i in range(n):
            for j in range(i + 1, n):
                d = abs(nums1[i] - nums1[j]) + abs(nums2[i] - nums2[j])
                if d < bd:
                    bd, bi, bj = d, i, j
        return [bi, bj]

