class Solution:
    def beautifulPair(self, nums1: List[int], nums2: List[int]) -> List[int]:
        n = len(nums1)
        pts = sorted(range(n), key=lambda i: (nums1[i], nums2[i]))
        best = [float('inf'), -1, -1]
        def cand(i, j):
            d = abs(nums1[i] - nums1[j]) + abs(nums2[i] - nums2[j])
            a, b = (i, j) if i < j else (j, i)
            if d < best[0] or (d == best[0] and (a, b) < (best[1], best[2])):
                best[0], best[1], best[2] = d, a, b
        def rec(lo, hi):
            if hi - lo <= 3:
                for a in range(lo, hi + 1):
                    for b in range(a + 1, hi + 1):
                        cand(pts[a], pts[b])
                return
            mid = (lo + hi) // 2
            mx = nums1[pts[mid]]
            rec(lo, mid)
            rec(mid + 1, hi)
            strip = [p for p in pts[lo:hi + 1] if abs(nums1[p] - mx) < best[0]]
            strip.sort(key=lambda p: nums1[p] + nums2[p])
            for a in range(len(strip)):
                ua = nums1[strip[a]] + nums2[strip[a]]
                for b in range(a + 1, len(strip)):
                    ub = nums1[strip[b]] + nums2[strip[b]]
                    if ub - ua >= best[0]:
                        break
                    cand(strip[a], strip[b])
        rec(0, n - 1)
        return [best[1], best[2]]

