class Solution {
public:
    vector<int> beautifulPair(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        vector<int> pts(n);
        iota(pts.begin(), pts.end(), 0);
        sort(pts.begin(), pts.end(), [&](int a, int b) {
            return nums1[a] != nums1[b] ? nums1[a] < nums1[b] : nums2[a] < nums2[b];
        });
        long long bd = LLONG_MAX; int bi = -1, bj = -1;
        auto cand = [&](int i, int j) {
            long long d = llabs(nums1[i] - nums1[j]) + llabs(nums2[i] - nums2[j]);
            int a = min(i, j), b = max(i, j);
            if (d < bd || (d == bd && (a < bi || (a == bi && b < bj)))) { bd = d; bi = a; bj = b; }
        };
        function<void(int, int)> rec = [&](int lo, int hi) {
            if (hi - lo <= 3) {
                for (int a = lo; a <= hi; a++)
                    for (int b = a + 1; b <= hi; b++) cand(pts[a], pts[b]);
                return;
            }
            int mid = (lo + hi) / 2, mx = nums1[pts[mid]];
            rec(lo, mid); rec(mid + 1, hi);
            vector<int> st;
            for (int t = lo; t <= hi; t++)
                if (llabs(nums1[pts[t]] - mx) < bd) st.push_back(pts[t]);
            sort(st.begin(), st.end(), [&](int a, int b) {
                return nums1[a] + nums2[a] < nums1[b] + nums2[b];
            });
            for (int a = 0; a < (int)st.size(); a++) {
                long long ua = nums1[st[a]] + nums2[st[a]];
                for (int b = a + 1; b < (int)st.size(); b++) {
                    long long ub = nums1[st[b]] + nums2[st[b]];
                    if (ub - ua >= bd) break;
                    cand(st[a], st[b]);
                }
            }
        };
        rec(0, n - 1);
        return {bi, bj};
    }
};

