class Solution {
    private int[] nums1, nums2;
    private long bd;
    private int bi, bj;
    private void cand(int i, int j) {
        long d = Math.abs(nums1[i] - nums1[j]) + Math.abs(nums2[i] - nums2[j]);
        int a = Math.min(i, j), b = Math.max(i, j);
        if (d < bd || (d == bd && (a < bi || (a == bi && b < bj)))) { bd = d; bi = a; bj = b; }
    }
    private void rec(List<Integer> pts, int lo, int hi) {
        if (hi - lo <= 3) {
            for (int a = lo; a <= hi; a++)
                for (int b = a + 1; b <= hi; b++) cand(pts.get(a), pts.get(b));
            return;
        }
        int mid = (lo + hi) / 2, mx = nums1[pts.get(mid)];
        rec(pts, lo, mid); rec(pts, mid + 1, hi);
        List<Integer> st = new ArrayList<>();
        for (int t = lo; t <= hi; t++)
            if (Math.abs(nums1[pts.get(t)] - mx) < bd) st.add(pts.get(t));
        st.sort((p, q) -> Long.compare(nums1[p] + nums2[p], nums1[q] + nums2[q]));
        for (int a = 0; a < st.size(); a++) {
            long ua = nums1[st.get(a)] + nums2[st.get(a)];
            for (int b = a + 1; b < st.size(); b++) {
                long ub = nums1[st.get(b)] + nums2[st.get(b)];
                if (ub - ua >= bd) break;
                cand(st.get(a), st.get(b));
            }
        }
    }
    public int[] beautifulPair(int[] nums1, int[] nums2) {
        this.nums1 = nums1; this.nums2 = nums2;
        int n = nums1.length;
        List<Integer> pts = new ArrayList<>();
        for (int i = 0; i < n; i++) pts.add(i);
        pts.sort((a, b) -> nums1[a] != nums1[b] ? nums1[a] - nums1[b] : nums2[a] - nums2[b]);
        bd = Long.MAX_VALUE; bi = -1; bj = -1;
        rec(pts, 0, n - 1);
        return new int[]{bi, bj};
    }
}

