var beautifulPair = function(nums1, nums2) {
    const n = nums1.length;
    const pts = [...Array(n).keys()].sort((a, b) => nums1[a] - nums1[b] || nums2[a] - nums2[b]);
    let bd = Infinity, bi = -1, bj = -1;
    const cand = (i, j) => {
        const d = Math.abs(nums1[i] - nums1[j]) + Math.abs(nums2[i] - nums2[j]);
        const a = Math.min(i, j), b = Math.max(i, j);
        if (d < bd || (d === bd && (a < bi || (a === bi && b < bj)))) { bd = d; bi = a; bj = b; }
    };
    const rec = (lo, hi) => {
        if (hi - lo <= 3) {
            for (let a = lo; a <= hi; a++)
                for (let b = a + 1; b <= hi; b++) cand(pts[a], pts[b]);
            return;
        }
        const mid = (lo + hi) >> 1, mx = nums1[pts[mid]];
        rec(lo, mid); rec(mid + 1, hi);
        const st = [];
        for (let t = lo; t <= hi; t++)
            if (Math.abs(nums1[pts[t]] - mx) < bd) st.push(pts[t]);
        st.sort((p, q) => (nums1[p] + nums2[p]) - (nums1[q] + nums2[q]));
        for (let a = 0; a < st.length; a++) {
            const ua = nums1[st[a]] + nums2[st[a]];
            for (let b = a + 1; b < st.length; b++) {
                const ub = nums1[st[b]] + nums2[st[b]];
                if (ub - ua >= bd) break;
                cand(st[a], st[b]);
            }
        }
    };
    rec(0, n - 1);
    return [bi, bj];
};
